@BeforeEach
  void startClientAndServer() throws Exception {
    testServer = TestServer.create();
    server = testServer.getServer();

    scriptable = new GatedSubscriptionServiceSet(server);
    for (EndpointConfig endpoint : server.getConfig().getEndpoints()) {
      server.addServiceSet(endpoint.getPath(), scriptable);
    }

    server.startup().get();

    client =
        TestClient.create(
            server,
            cfg ->
                cfg.setRequestTimeout(uint(REQUEST_TIMEOUT_MILLIS))
                    // No Session keep-alive traffic: the only requests in flight during a test are
                    // the ones it makes.
                    .setKeepAliveInterval(uint(REQUEST_TIMEOUT_MILLIS)));
    client.connect();

    subscription = new OpcUaSubscription(client);
  }

@AfterEach
  void stopClientAndServer() throws Exception {
    scriptable.releaseCreateGate();
    scriptable.failParkedRequests(StatusCodes.Bad_NoSubscription);
    try {
      client.disconnectAsync().get(5, TimeUnit.SECONDS);
    } catch (Exception ignored) {
      // A lifecycle frozen by a StackOverflowError in the hand-off cannot be shut down cleanly.
      // Tolerated so teardown does not mask the assertion that detected it; the Server shutdown
      // below releases what can be released.
    } finally {
      server.shutdown().get(10, TimeUnit.SECONDS);
    }
  }

@BeforeEach
    void setUp() {
        new TransactionTemplate(txManager).executeWithoutResult(status -> {
            var user = new UserData();
            user.setLoginName(PUBLISHER_LOGIN);
            em.persist(user);

            var token = new PersonalAccessToken();
            token.setUser(user);
            token.setValue(PUBLISHER_LOGIN + "_token");
            token.setCreatedTimestamp(LocalDateTime.now());
            token.setActive(true);
            em.persist(token);

            // The namespace exists, the extension does not: this is a first-time publication.
            var namespace = new Namespace();
            namespace.setName(NAMESPACE);
            em.persist(namespace);

            var membership = new NamespaceMembership();
            membership.setUser(user);
            membership.setNamespace(namespace);
            membership.setRole(NamespaceMembership.ROLE_OWNER);
            em.persist(membership);
            em.flush();

            namespaceId = namespace.getId();
            userId = user.getId();
            tokenId = token.getId();
        });
    }

@AfterEach
    void tearDown() {
        new TransactionTemplate(txManager).executeWithoutResult(status -> {
            em.createQuery("delete from ExtensionVersion ev where ev.extension.namespace.name = :namespace")
                    .setParameter("namespace", NAMESPACE).executeUpdate();
            em.createQuery("delete from Extension e where e.namespace.name = :namespace")
                    .setParameter("namespace", NAMESPACE).executeUpdate();
            em.createQuery("delete from NamespaceMembership nm where nm.namespace.name = :namespace")
                    .setParameter("namespace", NAMESPACE).executeUpdate();
            em.createQuery("delete from PersonalAccessToken t where t.user.loginName = :login")
                    .setParameter("login", PUBLISHER_LOGIN).executeUpdate();
            em.createQuery("delete from Namespace n where n.name = :namespace")
                    .setParameter("namespace", NAMESPACE).executeUpdate();
            em.createQuery("delete from UserData u where u.loginName = :login")
                    .setParameter("login", PUBLISHER_LOGIN).executeUpdate();
        });
    }

