@BeforeAll
  static void setUp() throws Exception {
    zkServer = new TestingServer();
    cleanup.deferAfterAll(zkServer);
    zkServer.start();

    System.setProperty("dubbo.application.qos-enable", "false");
    cleanup.deferAfterAll(() -> System.clearProperty("dubbo.application.qos-enable"));
    Field field = NetUtils.class.getDeclaredField("LOCAL_ADDRESS");
    field.setAccessible(true);
    InetAddress originalLocalAddress = (InetAddress) field.get(null);
    field.set(null, InetAddress.getLoopbackAddress());
    cleanup.deferAfterAll(() -> field.set(null, originalLocalAddress));
  }

@BeforeAll
  void setUp() throws ClientException {
    container.start();
    cleanup.deferAfterAll(container::close);
    ClientConfiguration clientConfiguration =
        ClientConfiguration.newBuilder()
            .setEndpoints(container.endpoints)
            .setRequestTimeout(Duration.ofSeconds(10))
            .build();
    Map<String, FilterExpression> subscriptionExpressions = new HashMap<>();
    subscriptionExpressions.put(TOPIC, new FilterExpression(TAG, FilterExpressionType.TAG));
    consumer =
        provider
            .newSimpleConsumerBuilder()
            .setClientConfiguration(clientConfiguration)
            .setConsumerGroup(CONSUMER_GROUP)
            .setAwaitDuration(Duration.ofSeconds(5))
            .setSubscriptionExpressions(subscriptionExpressions)
            .build();
    cleanup.deferAfterAll(() -> ((ClientImpl) consumer).stopAsync());
    producer =
        provider
            .newProducerBuilder()
            .setClientConfiguration(clientConfiguration)
            .setTopics(TOPIC)
            .build();
    cleanup.deferAfterAll(producer);
  }

