@Before
    public void setUp() throws Exception {
        conn = DriverManager.getConnection(URL, "sa", "");
        try (Statement st = conn.createStatement()) {
            st.execute("DROP ALL OBJECTS");
            st.execute("CREATE SCHEMA test");
            st.execute("CREATE TABLE test.customer (id INT PRIMARY KEY, name VARCHAR(64))");
            st.execute("CREATE TABLE test.category (id INT PRIMARY KEY, label VARCHAR(64))");
            st.execute("CREATE TABLE test.product  (id INT PRIMARY KEY, name VARCHAR(64), category_id INT,"
                    + " FOREIGN KEY (category_id) REFERENCES test.category(id))");
            st.execute("CREATE TABLE test.orders ("
                    + " id INT PRIMARY KEY,"
                    + " customer_id INT,"
                    + " product_id INT,"
                    + " order_date DATE,"
                    + " amount DECIMAL(10,2),"
                    + " qty INT,"
                    + " FOREIGN KEY (customer_id) REFERENCES test.customer(id),"
                    + " FOREIGN KEY (product_id)  REFERENCES test.product(id))");
            st.execute("INSERT INTO test.customer VALUES (1, 'alice'), (2, 'bob')");
            st.execute("INSERT INTO test.category VALUES (1, 'books')");
            st.execute("INSERT INTO test.product  VALUES (1, 'a', 1), (2, 'b', 1)");
            st.execute("INSERT INTO test.orders   VALUES (1, 1, 1, '2024-01-01', 9.99, 1)");
        }
    }

@After
    public void tearDown() throws Exception {
        if (conn != null) {
            try (Statement st = conn.createStatement()) {
                st.execute("DROP ALL OBJECTS");
            }
            conn.close();
        }
    }

@Before
    public void setUp() {
        Provenance rule = new Provenance(Provenance.Source.RULE, "rule:test", 0.8);
        schema = new DraftSchema("Main");

        sales = new DraftCube("Sales", "fact_sales", rule);

        customer = new DraftDimension("customer", DraftDimension.Type.STANDARD, rule);
        customer.setSourceTable("dim_customer");
        customer.setForeignKey("customer_id");
        DraftHierarchy custHier = new DraftHierarchy("customer", "id", rule);
        custHier.levels().add(new DraftLevel("name", "name", DraftLevel.Type.REGULAR, rule));
        customer.hierarchies().add(custHier);
        sales.dimensions().add(customer);

        amount = new DraftMeasure("amount", "amount_col", DraftMeasure.Aggregator.SUM, rule);
        sales.measures().add(amount);
        DraftMeasure qty = new DraftMeasure("qty", "qty_col", DraftMeasure.Aggregator.SUM, rule);
        sales.measures().add(qty);

        schema.cubes().add(sales);

        DraftDimension time = new DraftDimension("Time", DraftDimension.Type.TIME, rule);
        schema.sharedDimensions().add(time);
    }

